package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsTax decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsIncEd string // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var taxRec TaxRec

var taxFile *os.File
var taxScanner *bufio.Scanner
var taxFileOpen bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func fitPic(intDigits int, scale int32, v decimal.Decimal) decimal.Decimal {
	// truncate/round already done by caller; just drop high-order digits
	if intDigits <= 0 {
		return v
	}
	pow := decimal.NewFromInt(10).Pow(decimal.NewFromInt(int64(intDigits)))
	// for non-negative values Mod works; handle negative by sign
	if v.IsNegative() {
		av := v.Abs().Mod(pow)
		return av.Neg()
	}
	return v.Mod(pow)
}

func formatEdited(pic string, v decimal.Decimal) string {
	// find dot
	dotIdx := strings.Index(pic, ".")
	var intPat, fracPat string
	if dotIdx >= 0 {
		intPat = pic[:dotIdx]
		fracPat = pic[dotIdx+1:]
	} else {
		intPat = pic
		fracPat = ""
	}
	// count placeholders
	intPlace := 0
	for _, c := range intPat {
		if c == 'Z' || c == '9' {
			intPlace++
		}
	}
	fracPlace := 0
	for _, c := range fracPat {
		if c == 'Z' || c == '9' {
			fracPlace++
		}
	}
	// round to fracPlace
	av := v.Abs().Round(int32(fracPlace))
	// scaled integer
	shifted := av.Shift(int32(fracPlace))
	// get int64 parts (values are small enough)
	s64 := shifted.IntPart()
	var fracVal int64
	var intVal int64
	if fracPlace > 0 {
		pow10 := int64(1)
		for i := 0; i < fracPlace; i++ {
			pow10 *= 10
		}
		fracVal = s64 % pow10
		if fracVal < 0 {
			fracVal = -fracVal
		}
		intVal = s64 / pow10
	} else {
		fracVal = 0
		intVal = s64
	}
	// drop high-order digits
	modulo := int64(1)
	for i := 0; i < intPlace; i++ {
		modulo *= 10
	}
	if modulo != 0 && intPlace > 0 {
		intVal = intVal % modulo
		if intVal < 0 {
			intVal = -intVal
		}
	}
	intStr := fmt.Sprintf("%0*d", intPlace, intVal)
	fracStr := ""
	if fracPlace > 0 {
		fracStr = fmt.Sprintf("%0*d", fracPlace, fracVal)
	}
	// build integer part output with suppression
	// map placeholder digits
	digits := []rune(intStr)
	outInt := make([]rune, 0, len(intPat))
	// determine suppression: find index of last leading-zero Z run
	// suppression active until first non-zero digit
	// locate position of first non-zero in digits
	firstNZ := -1
	for i, d := range digits {
		if d != '0' {
			firstNZ = i
			break
		}
	}
	// if all zero, firstNZ stays -1
	di := 0
	for _, pc := range intPat {
		if pc == 'Z' || pc == '9' {
			d := digits[di]
			if pc == 'Z' {
				if firstNZ == -1 {
					// all zero: suppress this Z
					outInt = append(outInt, ' ')
				} else if di < firstNZ {
					outInt = append(outInt, ' ')
				} else {
					outInt = append(outInt, d)
				}
			} else { // '9'
				outInt = append(outInt, d)
			}
			di++
		} else if pc == ',' {
			// comma: if everything after? Standard: comma in suppressed zone becomes space.
			// Determine if suppressed up to this point: check if all digits so far (and including future?) Actually comma is space if all integer digits to the left are suppressed (i.e., di <= firstNZ or all zero).
			// di is number of digits consumed so far (left of comma).
			suppressed := false
			if firstNZ == -1 {
				suppressed = true
			} else if di <= firstNZ {
				suppressed = true
			}
			if suppressed {
				outInt = append(outInt, ' ')
			} else {
				outInt = append(outInt, ',')
			}
		} else {
			outInt = append(outInt, pc)
		}
	}
	result := string(outInt)
	if dotIdx >= 0 {
		result += "." + fracStr
		// Note: fracPat may contain more literals? only 9s here.
	}
	return result
}

func parseIncomeField(s string) decimal.Decimal {
	// s length 8, digits only (implied 2 decimals). Spaces => zero.
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits (and possible sign?)
	// filter digits
	var b strings.Builder
	neg := false
	for _, c := range t {
		if c >= '0' && c <= '9' {
			b.WriteRune(c)
		} else if c == '-' {
			neg = true
		}
	}
	ds := b.String()
	if ds == "" {
		return decimal.NewFromInt(0)
	}
	// strip leading zeros for parsing but keep at least one
	ds = strings.TrimLeft(ds, "0")
	if ds == "" {
		ds = "0"
	}
	n, _ := decimal.NewFromString(ds)
	// original had exactly implied scale; but ds trimmed zeros on left only, scale still 2 relative to original width? If field had spaces? Assume digits represent full value. Since we trimmed spaces, leading spaces were zeros? Actually numeric field is zero-padded, so trimming spaces is fine; value = integer of digits shifted -2. But if field was short due to padding? We padded with spaces, trimmed them, digits remain correct.
	// However if digits length < original due to spaces, still shift -2 is correct because implied decimal is fixed.
	// But our ds after TrimLeft may have fewer digits; New + Shift still correct? Example "000100000" -> trimmed "100000" -> 100000 *10^-2 =1000.00 correct.
	v := decimal.New(n.IntPart(), -2)
	// Adjust if digit count was less than 8 due to blank? No, LINE SEQUENTIAL pads spaces, digits are left part. Still correct.
	if neg {
		v = v.Neg()
	}
	return v
}

func MainPara() {
	WsEofFlag = "N"
	WsTax = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalTax = decimal.NewFromInt(0)
	WsCount = 0
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		// If file does not exist, treat as empty (COBOL OPEN INPUT would fail, but tests always provide file)
		// To match behaviour, treat as empty input.
		if os.IsNotExist(err) {
			taxScanner = bufio.NewScanner(strings.NewReader(""))
			taxFileOpen = false
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		taxFileOpen = true
		taxScanner = bufio.NewScanner(taxFile)
		// allow long lines
		taxScanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if taxFileOpen {
		taxFile.Close()
	}
	WsTotalEd = formatEdited("ZZ,ZZZ,ZZ9.99", WsTotalTax)
	countDisp := fmt.Sprintf("%03d", WsCount%1000)
	// DISPLAY "TAXPAYERS: " WS-COUNT " TOTAL TAX: " WS-TOTAL-ED
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countDisp, WsTotalEd)
}

func ReadPara() {
	if taxScanner == nil || !taxScanner.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := taxScanner.Text()
	// Scanner strips \n and \r\n; need to handle \r leftover
	if strings.HasSuffix(line, "\r") {
		line = strings.TrimSuffix(line, "\r")
	}
	// Pad with spaces on right to record length 13, truncate if longer
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	id := line[0:5]
	incField := line[5:13]
	taxRec.TrId = id
	taxRec.TrIncome = parseIncomeField(incField)
}

func ProcessPara() {
	lim10000 := decimal.New(1000000, -2)
	lim40000 := decimal.New(4000000, -2)
	rate10 := decimal.New(10, -2)
	rate20 := decimal.New(20, -2)
	rate30 := decimal.New(30, -2)
	c1000 := decimal.New(100000, -2)
	c7000 := decimal.New(700000, -2)
	c10000 := decimal.New(1000000, -2)
	c40000 := decimal.New(4000000, -2)
	if taxRec.TrIncome.Cmp(lim10000) <= 0 {
		v := taxRec.TrIncome.Mul(rate10)
		v = v.Round(2)
		v = fitPic(7, 2, v)
		WsTax = v
	} else {
		if taxRec.TrIncome.Cmp(lim40000) <= 0 {
			v := taxRec.TrIncome.Sub(c10000).Mul(rate20).Add(c1000)
			v = v.Round(2)
			v = fitPic(7, 2, v)
			WsTax = v
		} else {
			v := taxRec.TrIncome.Sub(c40000).Mul(rate30).Add(c7000)
			v = v.Round(2)
			v = fitPic(7, 2, v)
			WsTax = v
		}
	}
	wnet := taxRec.TrIncome.Sub(WsTax)
	wnet = wnet.Truncate(2)
	wnet = fitPic(7, 2, wnet)
	WsNet = wnet
	WsTotalTax = WsTotalTax.Add(WsTax)
	WsTotalTax = fitPic(9, 2, WsTotalTax)
	WsCount = (WsCount + 1) % 1000
	WsIncEd = formatEdited("ZZZ,ZZ9.99", taxRec.TrIncome)
	WsTaxEd = formatEdited("ZZZ,ZZ9.99", WsTax)
	WsNetEd = formatEdited("ZZZ,ZZ9.99", WsNet)
	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	ReadPara()
}

func main() {
	MainPara()
}
